<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/koneksi.php';
require_once __DIR__ . '/../config/auth.php';
$user = require_role('teller');
$stats = ['today' => 0, 'today_amount' => 0, 'pending' => 0, 'arrears' => 0]; $recent = [];
try {
    $row = $pdo->query("SELECT COUNT(*) AS jumlah, COALESCE(SUM(nominal),0) AS nominal FROM transaksi_payment_gateway WHERE tanggal_transaksi=CURDATE()")->fetch();
    $stats['today'] = (int) ($row['jumlah'] ?? 0); $stats['today_amount'] = (int) ($row['nominal'] ?? 0);
    $stats['pending'] = (int) $pdo->query("SELECT COUNT(*) FROM transaksi_payment_gateway WHERE status_transaksi='pending'")->fetchColumn();
    $stats['arrears'] = (int) $pdo->query("SELECT COUNT(*) FROM tagihan_spp WHERE status='TUNGGAKAN'")->fetchColumn();
    $recent = $pdo->query("SELECT t.order_id, COALESCE(va.nomor_va, t.virtual_account) AS virtual_account, s.nama, t.nominal, t.status_transaksi, COALESCE(t.waktu_transaksi,t.created_at) AS waktu FROM transaksi_payment_gateway t LEFT JOIN siswa s ON s.id_siswa=t.id_siswa LEFT JOIN virtual_account va ON va.id_siswa=t.id_siswa AND va.status='aktif' ORDER BY waktu DESC LIMIT 8")->fetchAll();
} catch (Throwable $e) { error_log('Dashboard teller: ' . $e->getMessage()); }
function trp(int $value): string { return 'Rp ' . number_format($value, 0, ',', '.'); }
function tpill(string $status): string { $class = in_array($status, ['settlement','capture'], true) ? 'success' : (in_array($status, ['pending'], true) ? 'warning' : (in_array($status, ['deny','cancel','expire'], true) ? 'danger' : 'neutral')); return '<span class="status-pill ' . $class . '">' . htmlspecialchars($status, ENT_QUOTES, 'UTF-8') . '</span>'; }
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Dashboard Teller | SPP Bina Bangsa</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Material+Symbols+Rounded:opsz,wght,FILL,GRAD@20..48,400,0,0"><link rel="stylesheet" href="../assets/css/teller/sidebar.css"><link rel="stylesheet" href="../assets/css/teller/dashboard.css"></head><body>
<?php require __DIR__ . '/partials/sidebar.php'; ?><main class="staff-main"><header class="staff-header"><div><h1>Dashboard Teller</h1><p>Cari siswa, cek VA, dan pantau status pembayaran.</p></div><div class="staff-role"><strong><?= htmlspecialchars((string) $user['nama'], ENT_QUOTES, 'UTF-8') ?></strong>Operasional read-only</div></header>
<section class="staff-stats"><article class="staff-card blue"><span>Transaksi hari ini</span><strong><?= $stats['today'] ?></strong><small>Payment gateway</small></article><article class="staff-card green"><span>Nominal hari ini</span><strong><?= trp($stats['today_amount']) ?></strong><small>Total transaksi masuk</small></article><article class="staff-card orange"><span>Menunggu</span><strong><?= $stats['pending'] ?></strong><small>Perlu dipantau</small></article><article class="staff-card red" id="tunggakan"><span>Tunggakan aktif</span><strong><?= $stats['arrears'] ?></strong><small>Tagihan melewati jatuh tempo</small></article></section>
<section class="staff-grid"><article class="staff-panel" id="pencarian"><h2>Pencarian cepat</h2><p>Gunakan NIS, nama siswa, atau nomor VA.</p><form class="quick-search" method="get" action="dashboard.php"><input name="q" value="<?= htmlspecialchars((string) ($_GET['q'] ?? ''), ENT_QUOTES, 'UTF-8') ?>" placeholder="Contoh: 8800012345"><button type="submit">Cari data siswa</button></form><?php if (isset($_GET['q'])): ?><p style="margin:16px 0 0;color:var(--staff-muted)">Pencarian akan disambungkan ke daftar monitoring pada tahap berikutnya.</p><?php endif; ?></article><article class="staff-panel"><h2>Aturan layanan</h2><p>Teller memantau transaksi yang diterima payment gateway.</p><p style="line-height:1.7">Pembayaran tidak diterima secara tunai. Status lunas hanya berasal dari transaksi yang berhasil divalidasi sistem.</p></article></section>
<section class="staff-panel" id="transaksi" style="margin-top:18px"><h2>Transaksi terbaru</h2><p>Gunakan data ini untuk membantu pencarian dan klarifikasi administrasi.</p><div class="staff-table-wrap"><table class="staff-table"><thead><tr><th>Order ID</th><th>Siswa</th><th>VA</th><th>Nominal</th><th>Status</th></tr></thead><tbody><?php if (!$recent): ?><tr><td class="empty-state" colspan="5">Belum ada transaksi.</td></tr><?php else: foreach ($recent as $row): ?><tr><td><?= htmlspecialchars($row['order_id'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($row['nama'] ?? 'Tidak ditemukan', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($row['virtual_account'], ENT_QUOTES, 'UTF-8') ?></td><td><?= trp((int) $row['nominal']) ?></td><td><?= tpill((string) $row['status_transaksi']) ?></td></tr><?php endforeach; endif; ?></tbody></table></div></section></main></body></html>
